package dev.kuan.kuanperion.automation.visitor;
import dev.kuan.kuanperion.automation.*;import java.util.*;import java.nio.file.*;
public final class VisitorAcquisitionTest {
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static VisitorPolicy policy(){var p=VisitorTaskTest.POLICY;var old=p.rules();var rules=new VisitorValuation.Rules(old.visitors(),old.materialIds(),old.maximumOfferCoins(),10000,old.minimumCopper());return new VisitorPolicy(rules,p.threshold(),p.maxVisitors(),p.timeoutSeconds(),p.cooldownSeconds(),p.onlyWhileFarming(),Map.of("ENCHANTED_WHEAT",new BazaarAcquisitionPlan.Material("minecraft:wheat",64,10000)));}
 static VisitorTaskTest.H buying(){var h=new VisitorTaskTest.H();h.f.inventory.put(9,VisitorSubmissionTest.EMPTY);h.f.acquireAllowed=true;check(h.task.request(policy(),true,0),"explicit purchase policy");for(int i=0;i<10&&h.f.commands.isEmpty();i++)h.tick();h.arrive(0);for(int i=0;i<20&&h.f.opens==0;i++)h.tick();h.f.show();for(int i=0;i<20&&h.f.acquisitions==0;i++)h.tick();check(h.task.state()==VisitorTask.State.ACQUIRING&&h.f.acquisitions==1&&h.f.clicks==0,"missing authorized material starts one child under same root, not submission");return h;}
 public static void main(String[]args)throws Exception{
  var h=buying();check(h.f.acquiredBudget.limit()==10000&&h.session.holdsFarming()&&h.f.pauses==1,"original run budget/Farm hold retained");h.task.onSystemMessage(1,"[Bazaar] Bought 64x Enchanted Wheat for 100 coins!");check(h.f.acquisitionMessages==1,"GAME routed to buying child");h.f.acquisition=VisitorTask.Acquisition.COMPLETE;h.f.inventory=VisitorSubmissionTest.before();h.tick();for(int i=0;i<20&&h.f.opens<2;i++)h.tick();check(h.f.opens==2,"reopens same dual-identity Visitor after purchase");h.f.show();for(int i=0;i<20&&h.f.clicks==0;i++)h.tick();check(h.f.clicks==1&&h.f.acquisitions==1&&h.task.state()==VisitorTask.State.WAIT_SUBMISSION,"fresh identical offer revalued then normal protected submission");h.task.cancel(h.now);
  h=buying();h.f.acquisition=VisitorTask.Acquisition.UNCERTAIN;h.tick();check(!h.task.active()&&h.f.clicks==0&&h.f.stops==1,"ambiguous spend stops parent without return/retry");
  h=buying();h.f.manual=true;h.tick();check(!h.task.active()&&h.f.acquisitionCancels>0&&h.f.clicks==0,"manual cancellation reaches child");
  h=buying();h.f.acquisition=VisitorTask.Acquisition.COMPLETE;h.tick();for(int i=0;i<20&&h.f.opens<2;i++)h.tick();h.f.show();for(int i=0;i<20&&h.task.active();i++)h.tick();check(h.f.acquisitions==1&&h.f.clicks==0,"unchanged missing materials never create buying loop");h.task.cancel(h.now);
  Path dir=Files.createTempDirectory("visitor-buy-settings-");try{Path path=dir.resolve("automation.json");var store=AutomationSettingsStore.load(path);store.setVisitorPolicy(policy());check(AutomationSettingsStore.load(path).visitorPolicy().equals(policy()),"native material allowlist/budget survive new jar/store");Files.writeString(path,"{\"schemaVersion\":1,\"visitor\":{\"buying\":{\"WHEAT\":{\"minecraftId\":\"minecraft:wheat\",\"stackLimit\":64,\"maximumCoins\":1.5}}}}");check(!AutomationSettingsStore.load(path).visitorPolicyValid(),"fractional or invalid purchase consent refuses");}finally{try(var paths=Files.walk(dir)){for(var p:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
  System.out.println("VisitorAcquisitionTest: PASS");
 }
}
